#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
A2A Mesh — Store-and-Forward implementation.
Offline node üzenetei várakoznak és visszakapcsoláskor újrakézbesítődnek.
Üzenetprioritás-címkék (P0–P2) és döntésnapló (decision log) támogatás.

Futtatható a repó gyökeréből:
    python store_and_forward.py
"""

import json
import time
import uuid
import threading
import queue
import os
from dataclasses import dataclass, field, asdict
from enum import IntEnum
from typing import Dict, List, Optional, Callable, Any
from collections import defaultdict


# ---------------------------------------------------------------------------
# Prioritás enum
# ---------------------------------------------------------------------------
class Priority(IntEnum):
    P0 = 0  # sürgős / szavazás
    P1 = 1  # normál
    P2 = 2  # laza csevegés

    @classmethod
    def from_str(cls, label: str) -> "Priority":
        mapping = {"P0": cls.P0, "P1": cls.P1, "P2": cls.P2}
        return mapping.get(label.upper(), cls.P1)


# ---------------------------------------------------------------------------
# Üzenet adatstruktúra
# ---------------------------------------------------------------------------
@dataclass
class MeshMessage:
    id: str
    sender: str
    recipient: str
    content: str
    priority: Priority = Priority.P1
    timestamp: float = field(default_factory=time.time)
    delivered: bool = False
    delivery_attempts: int = 0
    max_attempts: int = 50
    topic: Optional[str] = None
    msg_type: str = "chat"  # chat | vote | decision | capability

    def to_dict(self) -> dict:
        d = asdict(self)
        d["priority"] = self.priority.name
        return d

    @classmethod
    def from_dict(cls, d: dict) -> "MeshMessage":
        d = dict(d)
        d["priority"] = Priority.from_str(d.get("priority", "P1"))
        return cls(**d)


# ---------------------------------------------------------------------------
# Döntésnapló (decision log) — lezárult szavazások automatikus kerese
# ---------------------------------------------------------------------------
@dataclass
class DecisionRecord:
    decision_id: str
    topic: str
    summary: str
    votes: Dict[str, str]  # node_id -> vote ("yes"/"no"/"abstain")
    result: str
    timestamp: float = field(default_factory=time.time)
    closed: bool = True


class DecisionLog:
    """Lokális döntésnapló, amit minden node vezet és szinkronizál."""

    def __init__(self, persist_path: Optional[str] = None):
        self._records: Dict[str, DecisionRecord] = {}
        self._lock = threading.Lock()
        self._persist_path = persist_path
        if persist_path and os.path.exists(persist_path):
            self._load()

    def add(self, record: DecisionRecord) -> None:
        with self._lock:
            self._records[record.decision_id] = record
            self._persist()

    def get(self, decision_id: str) -> Optional[DecisionRecord]:
        with self._lock:
            return self._records.get(decision_id)

    def all_records(self) -> List[DecisionRecord]:
        with self._lock:
            return list(self._records.values())

    def summary_text(self) -> str:
        with self._lock:
            if not self._records:
                return "Nincs rögzített döntés."
            lines = []
            for r in sorted(self._records.values(), key=lambda x: x.timestamp):
                lines.append(
                    f"[{time.strftime('%Y-%m-%d %H:%M', time.localtime(r.timestamp))}] "
                    f"{r.decision_id[:8]} | {r.topic} | eredmény: {r.result} | "
                    f"szavazatok: {len(r.votes)}"
                )
            return "\n".join(lines)

    def _persist(self) -> None:
        if not self._persist_path:
            return
        data = {}
        for did, rec in self._records.items():
            data[did] = asdict(rec)
        try:
            with open(self._persist_path, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    def _load(self) -> None:
        try:
            with open(self._persist_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            for did, d in data.items():
                self._records[did] = DecisionRecord(**d)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Node — egy mesh résztvevő store-and-forward képességgel
# ---------------------------------------------------------------------------
class MeshNode:
    """
    Egy A2A Mesh node.
    - Offline állapotban bejövő üzenetek a store-and-forward queue-ban várakoznak.
    - Visszakapcsoláskor (reconnect) a várakozó üzenetek újrakézbesítődnek.
    - Prioritás szerinti sorrend: P0 előbb kerül kézbesítésre mint P2.
    """

    def __init__(self, node_id: str, persist_dir: str = ".a2a_store"):
        self.node_id = node_id
        self.online: bool = True
        self._lock = threading.Lock()

        # Per-recipient pending queue (store-and-forward)
        # recipient_id -> priority queue
        self._pending: Dict[str, List[MeshMessage]] = defaultdict(list)

        # Inbox: kézbesített üzenetek
        self.inbox: List[MeshMessage] = []
        self.inbox_lock = threading.Lock()

        # Callback ha üzenet érkezik
        self._on_message: Optional[Callable[[MeshMessage], None]] = None

        # Döntésnapló
        os.makedirs(persist_dir, exist_ok=True)
        self.decision_log = DecisionLog(
            persist_path=os.path.join(persist_dir, f"decisions_{node_id}.json")
        )

        # Aktív szavazások (vote_id -> dict)
        self._active_votes: Dict[str, dict] = {}
        self._persist_dir = persist_dir

        # Szál a háttérben futó redelivery-hez
        self._running = False
        self._redelivery_thread: Optional[threading.Thread] = None

    # -- online/offline vezérlés -------------------------------------------
    def go_offline(self) -> None:
        with self._lock:
            self.online = False
        print(f"[{self.node_id}] OFFLINE — bejövő üzenetek store-and-forward queue-ba kerülnek.")

    def go_online(self) -> None:
        with self._lock:
            self.online = True
        print(f"[{self.node_id}] ONLINE — várakozó üzenetek újrakézbesítése indul.")
        self._flush_pending()

    def is_online(self) -> bool:
        with self._lock:
            return self.online

    # -- üzenet küldése -----------------------------------------------------
    def send_message(
        self,
        recipient: str,
        content: str,
        priority: Priority = Priority.P1,
        msg_type: str = "chat",
        topic: Optional[str] = None,
    ) -> MeshMessage:
        msg = MeshMessage(
            id=str(uuid.uuid4()),
            sender=self.node_id,
            recipient=recipient,
            content=content,
            priority=priority,
            msg_type=msg_type,
            topic=topic,
        )
        self._route(msg)
        return msg

    def send_vote(
        self,
        recipient: str,
        vote_id: str,
        vote: str,
        topic: str,
        priority: Priority = Priority.P0,
    ) -> MeshMessage:
        """Szavazat küldése — P0 prioritás, hogy ne fulladjon a csevegésbe."""
        payload = json.dumps({"vote_id": vote_id, "vote": vote, "topic": topic})
        return self.send_message(
            recipient=recipient,
            content=payload,
            priority=priority,
            msg_type="vote",
            topic=topic,
        )

    # -- belső routing ------------------------------------------------------
    def _route(self, msg: MeshMessage) -> None:
        """
        A 'mesh' egyszerűsített routing-ja.
        Ha a címzett online, azonnal kézbesít.
        Ha offline, a store-and-forward queue-ba teszi.
        """
        # Ebben a demóban a node maga is lehet címzett (loopback)
        # vagy egy másik MeshNode példány a mesh registry-ben.
        target = _mesh_registry.get(msg.recipient)
        if target is not None:
            target.receive(msg)
        else:
            # Ismeretlen címzett — nálunk tároljuk amíg fel nem bukkan
            self._store_pending(msg.recipient, msg)

    # -- üzenet fogadása ----------------------------------------------------
    def receive(self, msg: MeshMessage) -> None:
        if not self.is_online():
            # Offline — store-and-forward
            self._store_pending(self.node_id, msg)
            return

        # Online — azonnali kézbesítés
        self._deliver(msg)

    def _store_pending(self, key: str, msg: MeshMessage) -> None:
        with self._lock:
            self._pending[key].append(msg)
        print(f"[{self.node_id}] STORE pending for '{key}': "
              f"{msg.priority.name} {msg.msg_type} from {msg.sender} "
              f"(queue size: {len(self._pending[key])})")

    def _deliver(self, msg: MeshMessage) -> None:
        msg.delivered = True
        msg.delivery_attempts += 1
        with self.inbox_lock:
            self.inbox.append(msg)

        # Üzenettípus szerinti feldolgozás
        if msg.msg_type == "vote":
            self._handle_vote(msg)
        elif msg.msg_type == "decision":
            self._handle_decision(msg)

        if self._on_message:
            try:
                self._on_message(msg)
            except Exception:
                pass

        print(f"[{self.node_id}] DELIVERED: {msg.priority.name} {msg.msg_type} "
              f"from {msg.sender}: {msg.content[:60]}")

    def _flush_pending(self) -> None:
        """Visszakapcsoláskor az összes várakozó üzenet újrakézbesítése,
        prioritás szerinti sorrendben (P0 előbb)."""
        with self._lock:
            pending = self._pending.pop(self.node_id, [])

        if not pending:
            return

        # Rendezés prioritás szerint
        pending.sort(key=lambda m: (int(m.priority), m.timestamp))

        print(f"[{self.node_id}] Redelivering {len(pending)} pending message(s)...")
        for msg in pending:
            if msg.delivery_attempts >= msg.max_attempts:
                print(f"[{self.node_id}] DROPPED (max attempts): {msg.id}")
                continue
            self._deliver(msg)
            time.sleep(0.05)  # szimulált hálózati késleltetés

    # -- szavazás kezelése --------------------------------------------------
    def start_vote(self, vote_id: str, topic: str, question: str) -> None:
        with self._lock:
            self._active_votes[vote_id] = {
                "topic": topic,
                "question": question,
                "votes": {},
                "started": time.time(),
            }
        print(f"[{self.node_id}] Szavazás indítva: {vote_id} — {question}")

    def _handle_vote(self, msg: MeshMessage) -> None:
        try:
            payload = json.loads(msg.content)
            vote_id = payload["vote_id"]
            vote = payload["vote"]
            topic = payload["topic"]
        except (json.JSONDecodeError, KeyError):
            return

        with self._lock:
            if vote_id not in self._active_votes:
                self._active_votes[vote_id] = {
                    "topic": topic,
                    "question": "(ismeretlen kérdés)",
                    "votes": {},
                    "started": time.time(),
                }
            self._active_votes[vote_id]["votes"][msg.sender] = vote

        print(f"[{self.node_id}] Szavazat rögzítve: {msg.sender} -> {vote} "
              f"({vote_id})")

    def close_vote(self, vote_id: str) -> Optional[DecisionRecord]:
        """Szavazás lezárása és döntésnaplóba kerülés (automatikus kerese)."""
        with self._lock:
            vdata = self._active_votes.pop(vote_id, None)

        if vdata is None:
            return None

        votes = vdata["votes"]
        yes_count = sum(1 for v in votes.values() if v == "yes")
        no_count = sum(1 for v in votes.values() if v == "no")
        abstain = sum(1 for v in votes.values() if v == "abstain")

        if yes_count > no_count:
            result = "accepted"
        elif no_count > yes_count:
            result = "rejected"
        else:
            result = "tie"

        record = DecisionRecord(
            decision_id=vote_id,
            topic=vdata["topic"],
            summary=vdata["question"],
            votes=dict(votes),
            result=result,
        )
        self.decision_log.add(record)

        # Döntés szétküldése a mesh-be (P0)
        decision_payload = json.dumps({
            "decision_id": vote_id,
            "result": result,
            "yes": yes_count,
            "no": no_count,
            "abstain": abstain,
            "topic": vdata["topic"],
        })
        # Broadcast minden ismert node-nak
        for nid in _mesh_registry:
            if nid != self.node_id:
                self.send_message(
                    recipient=nid,
                    content=decision_payload,
                    priority=Priority.P0,
                    msg_type="decision",
                    topic=vdata["topic"],
                )

        print(f"[{self.node_id}] Döntés lezárva: {vote_id} -> {result} "
              f"(yes={yes_count}, no={no_count}, abstain={abstain})")
        return record

    def _handle_decision(self, msg: MeshMessage) -> None:
        try:
            payload = json.loads(msg.content)
        except json.JSONDecodeError:
            return

        record = DecisionRecord(
            decision_id=payload["decision_id"],
            topic=payload.get("topic", ""),
            summary=f"Result: {payload.get('result','?')}",
            votes={},
            result=payload.get("result", "unknown"),
        )
        self.decision_log.add(record)
        print(f"[{self.node_id}] Döntésnapló frissítve: {record.decision_id} -> {record.result}")

    # -- inbox lekérdezés ---------------------------------------------------
    def get_inbox(self, priority_filter: Optional[Priority] = None) -> List[MeshMessage]:
        with self.inbox_lock:
            if priority_filter is not None:
                return [m for m in self.inbox if m.priority == priority_filter]
            return list(self.inbox)

    def pending_count(self) -> int:
        with self._lock:
            return sum(len(v) for v in self._pending.values())

    def set_on_message(self, callback: Callable[[MeshMessage], None]) -> None:
        self._on_message = callback

    # -- háttér redelivery loop (ha új node csatlakozik) -------------------
    def start_redelivery_loop(self) -> None:
        self._running = True
        self._redelivery_thread = threading.Thread(target=self._redelivery_loop, daemon=True)
        self._redelivery_thread.start()

    def stop_redelivery_loop(self) -> None:
        self._running = False

    def _redelivery_loop(self) -> None:
        """Periodikusan ellenőrzi, hogy korábban ismeretlen címzettek
        most már elérhetők-e a mesh registry-ben."""
        while self._running:
            with self._lock:
                keys = list(self._pending.keys())
            for key in keys:
                if key == self.node_id:
                    if self.is_online():
                        self._flush_pending()
                    continue
                target = _mesh_registry.get(key)
                if target is not None and target.is_online():
                    # Várakozó üzenetek átirányítása a most már online node-nak
                    with self._lock:
                        msgs = self._pending.pop(key, [])
                    msgs.sort(key=lambda m: (int(m.priority), m.timestamp))
                    for m in msgs:
                        target.receive(m)
                        time.sleep(0.02)
            time.sleep(1.0)


# ---------------------------------------------------------------------------
# Mesh registry — egyszerű node-fordító
# ---------------------------------------------------------------------------
_mesh_registry: Dict[str, MeshNode] = {}
_registry_lock = threading.Lock()


def register_node(node: MeshNode) -> None:
    with _registry_lock:
        _mesh_registry[node.node_id] = node


def unregister_node(node_id: str) -> None:
    with _registry_lock:
        _mesh_registry.pop(node_id, None)


def get_node(node_id: str) -> Optional[MeshNode]:
    with _registry_lock:
        return _mesh_registry.get(node_id)


def list_nodes() -> List[str]:
    with _registry_lock:
        return list(_mesh_registry.keys())


# ---------------------------------------------------------------------------
# Demó / fő program
# ---------------------------------------------------------------------------
def demo_store_and_forward() -> None:
    print("=" * 70)
    print("A2A Mesh — Store-and-Forward demó")
    print("Offline node üzenetei várakoznak, visszakapcsoláskor újrakézbesítődnek.")
    print("=" * 70)

    # Node-ok létrehozása
    alice = MeshNode("alice")
    bob = MeshNode("bob")
    carol = MeshNode("carol")

    register_node(alice)
    register_node(bob)
    register_node(carol)

    # Redelivery loop indítása (hasonló mesh heartbeat)
    for n in (alice, bob, carol):
        n.start_redelivery_loop()

    # 1. Bob offline megy
    print("\n--- 1. Bob offline megy ---")
    bob.go_offline()

    # 2. Alice és Carol üzeneteket küldenek Bob-nak
    print("\n--- 2. Üzenetek küldése Bob-nak (offline) ---")
    alice.send_message("bob", "Szia Bob, ez egy normál üzenet.", priority=Priority.P1)
    alice.send_message("bob", "FONTOS: szavazás indul 5 perc múlva!", priority=Priority.P0)
    carol.send_message("bob", "laza csevegés :)", priority=Priority.P2)
    carol.send_message("bob", "Még egy P2 üzenet.", priority=Priority.P2)
    alice.send_message("bob", "P0: sürgős döntés kell!", priority=Priority.P0)

    print(f"\nBob pending üzenetek száma: {bob.pending_count()}")

    # 3. Bob visszakapcsol — üzenetek újrakézbesítése prioritás szerint
    print("\n--- 3. Bob visszakapcsol — redelivery ---")
    bob.go_online()

    # 4. Inbox ellenőrzése — prioritás szerinti sorrend
    print("\n--- 4. Bob inbox (kézbesítési sorrend) ---")
    for m in bob.get_inbox():
        print(f"  {m.priority.name} | {m.msg_type:8s} | {m.sender:5s} | {m.content[:50]}")

    # 5. Szavazás demó
    print("\n--- 5. Szavazás indítása (P0 prioritás) ---")
    vote_id = str(uuid.uuid4())
    alice.start_vote(vote_id, "témazárás", "Lezárjuk a 'tömörítés' témát?")

    # Bob és Carol szavaznak (P0 üzenetek)
    bob.send_vote("alice", vote_id, "yes", "témazárás")
    carol.send_vote("alice", vote_id, "no", "témazárás")
    alice.send_vote("alice", vote_id, "yes", "témazárás")  # önszavazat

    # 6. Szavazás lezárása — döntésnaplóba kerül
    print("\n--- 6. Szavazás lezárása — automatikus döntésnapló ---")
    record = alice.close_vote(vote_id)
    if record:
        print(f"  Döntés: {record.result}")
        print(f"  Szavazatok: {record.votes}")

    # 7. Döntésnapló megtekintése minden node-on
    print("\n--- 7. Döntésnapló (Alice) ---")
    print(alice.decision_log.summary_text())

    time.sleep(1.5)  # várjuk a döntés szétküldését

    print("\n--- 7b. Döntésnapló (Bob) ---")
    print(bob.decision_log.summary_text())

    print("\n--- 7c. Döntésnapló (Carol) ---")
    print(carol.decision_log.summary_text())

    # 8. Offline -> online redelivery ismeretlen címzettel
    print("\n--- 8. Üzenet ismeretlen node-nak, majd csatlakozik ---")
    alice.send_message("dave", "Dave, csatlakozz!", priority=Priority.P1)
    print(f"Alice pending (ismeretlen címzett): {alice.pending_count()}")

    dave = MeshNode("dave")
    register_node(dave)
    dave.start_redelivery_loop()
    dave.go_online()

    time.sleep(2.5)  # redelivery loop időt ad

    print(f"\nDave inbox:")
    for m in dave.get_inbox():
        print(f"  {m.priority.name} | {m.sender:5s} | {m.content[:50]}")

    # 9. Takarítás
    print("\n--- 9. Leállítás ---")
    for n in (alice, bob, carol, dave):
        n.stop_redelivery_loop()

    print("\nDemó befejezve.")
    print("=" * 70)


if __name__ == "__main__":
    demo_store_and_forward()